package main

import (
	"bytes"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"github.com/WuKongIM/WuKongIM/pkg/transport"
	"io"
	"net"
	"net/http"
	_ "net/http/pprof"
	"os"
	"os/signal"
	"reflect"
	"runtime"
	"sort"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

// allocationCounters are sampled only around a dedicated diagnostic workload.
type allocationCounters struct {
 TotalAlloc uint64 `json:"total_alloc"`
 Mallocs uint64 `json:"mallocs"`
 NumGC uint32 `json:"num_gc"`
 HeapAlloc uint64 `json:"heap_alloc"`
}

func allocationSnapshot(forceGC bool) allocationCounters {
 if forceGC { runtime.GC() }
 var m runtime.MemStats
 runtime.ReadMemStats(&m)
 return allocationCounters{m.TotalAlloc,m.Mallocs,m.NumGC,m.HeapAlloc}
}

func remoteAllocationSnapshot(forceGC bool) allocationCounters {
 url := "http://127.0.0.1:6061/rpc-memory"
 if forceGC { url += "?gc=1" }
 resp,err := (&http.Client{Timeout:10*time.Second}).Get(url)
 check(err);defer resp.Body.Close()
 if resp.StatusCode!=http.StatusOK {panic(resp.Status)}
 var result allocationCounters
 check(json.NewDecoder(resp.Body).Decode(&result))
 return result
}

type discovery string

func (d discovery) Resolve(transport.NodeID) (string, error) { return string(d), nil }
func main() {
	allocationProbe := flag.Bool("allocation-probe", false, "enable bounded server allocation snapshots")
	mode := flag.String("mode", "client", "server or client")
	addr := flag.String("addr", "127.0.0.1:7000", "peer/listen address")
	version := flag.String("version", "unknown", "revision label")
	workers := flag.Int("workers", 1, "bounded concurrency")
	shards := flag.Int("shards", 16, "active connection slots, 1 to 16")
	size := flag.Int("bytes", 64, "payload bytes")
	duration := flag.Duration("duration", 3*time.Second, "measurement duration")
	budgets := flag.String("budgets", "auto", "auto, on, or off; unsupported on fails")
	read := flag.Bool("read", false, "propagate cancellation into running read handler")
	profile := flag.String("pprof", "", "optional loopback-only diagnostic profile listener")
	fetchURL := flag.String("fetch", "", "loopback diagnostic URL")
	flag.Parse()
	if *fetchURL != "" {
		resp, err := (&http.Client{Timeout: 20 * time.Second}).Get(*fetchURL)
		check(err)
		defer resp.Body.Close()
		if resp.StatusCode != 200 {
			panic(resp.Status)
		}
		_, err = io.Copy(os.Stdout, resp.Body)
		check(err)
		return
	}
	if *budgets != "auto" && *budgets != "on" && *budgets != "off" {
		panic("invalid budgets mode")
	}
	if *profile != "" {
		host, _, err := net.SplitHostPort(*profile)
		if err != nil || (host != "127.0.0.1" && host != "::1") {
			panic("pprof must bind loopback")
		}
		listener, err := net.Listen("tcp", *profile)
		check(err)
		runtime.SetMutexProfileFraction(10)
		runtime.SetBlockProfileRate(1000000)
		go func() { check(http.Serve(listener, nil)) }()
	}

	if *shards < 1 || *shards > 16 || *workers < 1 || *workers > 16 || *size < 1 || *size > 65537 || *duration <= 0 || *duration > 60*time.Second {
		panic("invalid probe bounds")
	}
	if *mode == "server" {
  if *allocationProbe {
   mux := http.NewServeMux()
   mux.HandleFunc("/rpc-memory",func(w http.ResponseWriter,r *http.Request){
    counters := allocationSnapshot(r.URL.Query().Get("gc")=="1")
    check(json.NewEncoder(w).Encode(counters))
   })
   listener,err := net.Listen("tcp","127.0.0.1:6061");check(err)
   defer listener.Close()
   go func(){ _ = http.Serve(listener,mux) }()
  }
		s, e := transport.NewServer(transport.ServerConfig{NodeID: 2})
		check(e)
		options := transport.ServiceOptions{Concurrency: 64, QueueSize: 4096, MaxQueueBytes: 64 << 20}
		check(json.Unmarshal([]byte(fmt.Sprintf(`{"Timeout":30000000000,"QueueTimeout":5000000000,"CancelRunning":%t}`, *read)), &options))
		check(s.Handle(1, func(_ context.Context, p []byte) ([]byte, error) { return p, nil }, options))
		check(s.ListenAndServe(*addr))
		defer s.Stop()
		fmt.Println("RPC_PROBE_READY")
		check(json.NewEncoder(os.Stdout).Encode(map[string]any{"server_arch":runtime.GOARCH,"go_version":runtime.Version(),"version":*version,"options":options,"supports_queue_timeout":reflect.ValueOf(options).FieldByName("QueueTimeout").IsValid(),"supports_cancel_running":reflect.ValueOf(options).FieldByName("CancelRunning").IsValid()}))
		c := make(chan os.Signal, 1)
		signal.Notify(c, syscall.SIGTERM, syscall.SIGINT)
		<-c
		return
	}
	cfg := transport.ClientConfig{NodeID: 1, Discovery: discovery(*addr), PoolSize: 16}
	f := reflect.ValueOf(&cfg).Elem().FieldByName("RequestBudgets")
	if *budgets == "on" && !f.IsValid() {
		panic("request budgets unsupported")
	}
	budgeted := f.IsValid() && *budgets != "off"
	if f.IsValid() {
		f.SetBool(budgeted)
	}
	c, e := transport.NewClient(cfg)
	check(e)
	defer c.Stop()
	payload := bytes.Repeat([]byte{0x5a}, *size)
	call := func(shard int) error {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		p, e := c.Call(ctx, 2, uint64(shard), transport.PriorityRPC, 1, payload)
		if e != nil {
			return e
		}
		if !bytes.Equal(p, payload) {
			return fmt.Errorf("payload mismatch")
		}
		return nil
	}
	for i := 0; i < *shards; i++ {
		check(call(i))
	}
	samples := make([][]int64, *workers)
	for w := range samples {
		samples[w] = make([]int64, 0, 100000)
	}
	runtime.GC()
	var serverBefore,serverAfter allocationCounters
	if *allocationProbe { serverBefore=remoteAllocationSnapshot(true) }
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	var wg sync.WaitGroup
	var errors atomic.Int64
	var capped atomic.Bool
	start := time.Now()
	stop := start.Add(*duration)
	for w := 0; w < *workers; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			times := samples[w]
			for time.Now().Before(stop) {
				t := time.Now()
				e := call(w % *shards)
				if e != nil {
					errors.Add(1)
					continue
				}
				times = append(times, time.Since(t).Nanoseconds())
				if len(times) >= 1000000 {
					capped.Store(true)
					break
				}
			}
			samples[w] = times
		}(w)
	}
	wg.Wait()
	elapsed := time.Since(start)
	if *allocationProbe { serverAfter=remoteAllocationSnapshot(false) }
	runtime.ReadMemStats(&after)
	workerCounts := make([]int, len(samples))
	for i, sample := range samples {
		workerCounts[i] = len(sample)
	}
	all := []int64{}
	for _, s := range samples {
		all = append(all, s...)
	}
	sort.Slice(all, func(i, j int) bool { return all[i] < all[j] })
	if len(all) == 0 {
		panic("no successful calls")
	}
	percentile := func(p float64) float64 { return float64(all[int(float64(len(all)-1)*p)]) / 1e6 }
	var total int64
	for _, v := range all {
		total += v
	}
	json.NewEncoder(os.Stdout).Encode(map[string]any{"server_allocation":map[string]any{"enabled":*allocationProbe,"before":serverBefore,"after":serverAfter,"bytes_per_call":float64(serverAfter.TotalAlloc-serverBefore.TotalAlloc)/float64(len(all)),"allocs_per_call":float64(serverAfter.Mallocs-serverBefore.Mallocs)/float64(len(all))},"shards": *shards, "arch": runtime.GOARCH, "worker_counts": workerCounts, "sample_cap_hit": capped.Load(), "client_mallocs_per_call": float64(after.Mallocs-before.Mallocs) / float64(len(all)), "client_gc_cycles": after.NumGC - before.NumGC, "version": *version, "go_version": runtime.Version(), "workers": *workers, "payload_bytes": *size, "request_budgets": budgeted, "observer_enabled": false, "profiling_enabled": *profile != "", "calls": len(all), "errors": errors.Load(), "elapsed_seconds": elapsed.Seconds(), "calls_per_second": float64(len(all)) / elapsed.Seconds(), "mean_ms": float64(total) / float64(len(all)) / 1e6, "p50_ms": percentile(.50), "p95_ms": percentile(.95), "p99_ms": percentile(.99), "client_alloc_bytes_per_call": float64(after.TotalAlloc-before.TotalAlloc) / float64(len(all))})
	if errors.Load() != 0 || capped.Load() {
		os.Exit(1)
	}
}
func check(e error) {
	if e != nil {
		panic(e)
	}
}

