					t.Fatalf("mutation canceled: %v", err)
				}
			case <-time.After(time.Second):
				t.Fatal("running request did not complete")
			}
			select {
			case <-finished:
			case <-time.After(time.Second):
				t.Fatal("owner not released")
			}
		})
	}
}
