from pathlib import Path
import json,statistics,sys
E=Path(__file__).resolve().parent
out={}
for batch in ['allocation','controls','overload','overload-allocation','overload-followup','final-timing','final-allocation']:
 p=E/(batch+'.json')
 if not p.exists():continue
 rows=json.loads(p.read_text());groups={}
 for r in rows:r['server']=r['server'].replace('final','candidate')
 for r in rows:
  x=r['result'];kind=r['label'].split('-')[0] if batch=='controls' else batch
  groups.setdefault((kind,x['shards']),[]).append(r)
 result={}
 for (kind,shards),rr in groups.items():
  aa=[r for r in rr if r['label'].startswith('aa-')]
  rr=[r for r in rr if not r['label'].startswith('aa-')]
  d={'medians':{},'pairs':[],'aa':{}}
  fields=['calls_per_second','p99_ms']
  allocation=rr[0]['result'].get('server_allocation',{}).get('enabled',False)
  if allocation:fields=['bytes_per_call','allocs_per_call']
  def val(r):return r['result']['server_allocation'] if allocation else r['result']
  for v in ['base','candidate']:
   chosen=[r for r in rr if r['server'].startswith(v)]
   if chosen:d['medians'][v]={k:statistics.median(val(r)[k] for r in chosen) for k in fields}
  if len(d['medians'])==2:
   d['changes']={k:100*(d['medians']['candidate'][k]/d['medians']['base'][k]-1) for k in fields}
   d['deltas']={k:d['medians']['candidate'][k]-d['medians']['base'][k] for k in fields}
  for i in range(0,len(rr)-1,2):
   a=next(r for r in rr[i:i+2] if r['server'].startswith('base'));b=next(r for r in rr[i:i+2] if r['server'].startswith('candidate'))
   d['pairs'].append({k:100*(val(b)[k]/val(a)[k]-1) for k in fields})
  for v in ['base','candidate']:
   vv=[r for r in aa if r['server'].startswith(v)]
   if len(vv)==2:d['aa'][v]={k:100*(val(vv[1])[k]/val(vv[0])[k]-1) for k in fields}
  result[f'{kind}-shards{shards}']=d
 out[batch]=result
(E/'extra-summary.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps(out,indent=2))

